def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")
    result = []
    stack = []
    current_group = ""

    for c in paren_string:
        if c == '(':
            if not current_group:
                stack.append(c)
                current_group += c
            else:
                stack.append(c)
                current_group += c
        elif c == ')':
            if stack:
                stack.pop()
                current_group += c
                if not stack:
                    result.append(current_group)
                    current_group = ""
            else:
                raise ValueError("Unbalanced parentheses")
    if stack:
        raise ValueError("Unbalanced parentheses")

    return result

