from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")
    result = []
    stack = []
    group_start = 0

    for i, char in enumerate(paren_string):
        if char == '(':
            if not stack:
                group_start = i
            stack.append(char)
        elif char == ')':
            stack.pop()
            if not stack:
                result.append(paren_string[group_start:i + 1])

    return result


