from typing import List

def parse_music(music_string: str) -> List[int]:
    music_notes = music_string.split()
    parsed_notes = []

    for note in music_notes:
        if note == 'o':
            parsed_notes.append(4)
        elif note == 'o|':
            parsed_notes.append(2)
        elif note == '.|':
            parsed_notes.append(1)

    return parsed_notes

