def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    flipped = []
    for char in string:
        if char.islower():
            flipped.append(char.upper())
        elif char.isupper():
            flipped.append(char.lower())
        else:
            flipped.append(char)
    return ''.join(flipped)

# Test cases
print(flip_case('Hello'))  # Output: 'hELLO'
print(flip_case('Python Programming'))  # Output: 'pYTHON pROGRAMMING'
print(flip_case('123$%#'))  # Output: '123$%#'
print(flip_case(''))  # Output: ''

def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    result = []
    for char in string:
        if char.isupper():
            result.append(char.lower())
        else:
            result.append(char.upper())
    return ''.join(result)

