def find_zero(xs: list):
    def newton_raphson(coefficients, initial_guess, iterations):
        x = initial_guess
        for _ in range(iterations):
            fx = sum([coeff * math.pow(x, i) for i, coeff in enumerate(coefficients)])
            fpx = sum([(i + 1) * coeff * math.pow(x, i) for i, coeff in enumerate(coefficients[1:])])
            if fpx == 0:
                break
            x = x - fx / fpx
        return x

    if len(xs) % 2 == 0 and xs[-1] != 0:
        initial_guess = 0
        iterations = 100
        zero_point = newton_raphson(xs, initial_guess, iterations)
        return zero_point
    else:
        raise ValueError("Input list should have even number of coefficients and largest non zero coefficient.")

# Test cases
