import math


def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])


def find_zero(xs: list):
    """ xs are coefficients of a polynomial.
    find_zero find x such that poly(x) = 0.
    find_zero returns only only zero point, even if there are many.
    Moreover, find_zero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> round(find_zero([1, 2]), 2) # f(x) = 1 + 2x
    -0.5
    >>> round(find_zero([-6, 11, -6, 1]), 2) # (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
    """

    def sign_change(lst):
        return [lst[i] * lst[i + 1] < 0 for i in range(len(lst) - 1)]

    def bisection(xs, a, b):
        while abs(a - b) > 1e-5:
            mid = (a + b) / 2
            if poly(xs, mid) == 0:
                return mid
            elif poly(xs, a) * poly(xs, mid) < 0:
                b = mid
            else:
                a = mid
        return (a + b) / 2

    x_values = [i for i in range(-100, 101)]
    poly_values = [poly(xs, x) for x in x_values]
    sign_changes = sign_change(poly_values)

    if True in sign_changes:
        index = sign_changes.index(True)
        return bisection(xs, x_values[index], x_values[index + 1])
    else:
        raise ValueError("No zero found in the given range.")


if __name__ == "__main__":
    print(round(find_zero([1, 2]), 2))  # f(x) = 1 + 2x
    print(round(find_zero([-6, 11, -6, 1]), 2))  # (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3

