    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if len(l) < 2:
        return True

    direction = l[1] - l[0]
    for i in range(2, len(l)):
        if direction == 0:
            direction = l[i] - l[i-1]
