def search(lst):
    '''
    You are given a non-empty list of positive integers. Return the greatest integer that is greater than 
    zero, and has a frequency greater than or equal to the value of the integer itself. 
    The frequency of an integer is the number of times it appears in the list.
    If no such a value exist, return -1.
    Examples:
        search([4, 1, 2, 2, 3, 1]) == 2
        search([1, 2, 2, 3, 3, 3, 4, 4, 4]) == 3
        search([5, 5, 4, 4, 4]) == -1
    '''
    # Create a dictionary to store the frequency of integers
    freq_dict = {}

    for num in lst:
        if num in freq_dict:
            freq_dict[num] += 1
        else:
            freq_dict[num] = 1

    # Iterate through the dictionary and find integers that satisfy the condition
    valid_integers = []
    for key, value in freq_dict.items():
        if key <= value:
            valid_integers.append(key)

    # Return the maximum valid integer if there is at least one, otherwise return -1
    if len(valid_integers) > 0:
        return max(valid_integers)
    else:
        return -1

