        if n < 2:
            return False
        for i in range(2, n):
            if n % i == 0:
                return False
        return True

    def hex_digit_to_decimal(hex_digit):
        if '0' <= hex_digit <= '9':
            return int(hex_digit)
        elif 'A' <= hex_digit <= 'F':
            return 10 + ord(hex_digit) - ord('A')
        else:
            raise ValueError(f"Invalid hex digit: {hex_digit}")

    prime_count = 0
    for hex_digit in num:
        decimal_digit = hex_digit_to_decimal(hex_digit)
        if is_prime(decimal_digit):
            prime_count += 1

    return prime_count

