def get_row(lst, x):
    coordinates = []

    for row_index, row in enumerate(lst):
        for col_index, value in enumerate(row):
            if value == x:
                coordinates.append((row_index, col_index))

    # Sort coordinates initially by rows in ascending order
    coordinates.sort(key=lambda coord: coord[0])

    # Sort coordinates of the row by columns in descending order
    sorted_coordinates = []
    current_row = -1
    row_coords = []
    for coord in coordinates:
        if coord[0] != current_row:
            if row_coords:
                row_coords.sort(key=lambda c: c[1], reverse=True)
                sorted_coordinates.extend(row_coords)
            current_row = coord[0]
            row_coords = [coord]
        else:
            row_coords.append(coord)
    if row_coords:
        row_coords.sort(key=lambda c: c[1], reverse=True)
        sorted_coordinates.extend(row_coords)

    return sorted_coordinates

