def check_dict_case(dict):
    if not dict:
        return False

    lower_case = 0
    upper_case = 0

    for key in dict:
        if not isinstance(key, str):
            return False

        if key.islower():
            lower_case += 1
        elif key.isupper():
            upper_case += 1
        else:
            return False

