def get_max_triples(n):
    def generate_array(n):
        return [i * i - i + 1 for i in range(1, n + 1)]

    def is_multiple_of_3(a, b, c):
        return (a + b + c) % 3 == 0

    a = generate_array(n)
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if is_multiple_of_3(a[i], a[j], a[k]):
                    count += 1
    return count

