def get_max_triples(n):
    def create_array(n):
        a = []
        for i in range(1, n + 1):
            a.append(i * i - i + 1)
        return a

    def count_triples(a):
        count = 0
        for i in range(len(a)):
            for j in range(i + 1, len(a)):
                for k in range(j + 1, len(a)):
                    if (a[i] + a[j] + a[k]) % 3 == 0:
                        count += 1
        return count

    a = create_array(n)
    return count_triples(a)

