def bf(planet1, planet2):
    planets = {
        "Mercury": 1,
        "Venus": 2,
        "Earth": 3,
        "Mars": 4,
        "Jupiter": 5,
        "Saturn": 6,
        "Uranus": 7,
        "Neptune": 8
    }

    if planet1 not in planets or planet2 not in planets:
        return ()

    planet1_index = planets[planet1]
    planet2_index = planets[planet2]

    if planet1_index > planet2_index:
        planet1_index, planet2_index = planet2_index, planet1_index

    result = []
    for planet, index in planets.items():
        if planet1_index < index < planet2_index:
            result.append((planet, index))

    result.sort(key=lambda x: x[1])
    return tuple([planet for planet, index in result])


